INSERT INTO `faq` (`id`, `category`, `keyword`, `question`, `answer`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'hardware', 'กระดาษติด,ดึงกระดาษไม่ได้,กระดาษค้าง', 'กระดาษติดในเครื่องพิมพ์ทำอย่างไร', 'ปิดเครื่องก่อน แล้วค่อยๆ ดึงกระดาษออกตามทิศทางที่กระดาษวิ่ง อย่าดึงย้อนทิศ จากนั้นเปิดฝาหลังเช็คว่ามีกระดาษค้างอยู่หรือไม่ เปิดเครื่องใหม่แล้วลองพิมพ์ทดสอบ', 1, '2026-07-12 19:51:46', NULL),
(2, 'hardware', 'หมึกหมด,เติมหมึก,หมึกไม่ออก,พิมพ์ไม่ออก', 'หมึกเพิ่งเติมแต่ยังพิมพ์ไม่ออก', 'ลอง print head cleaning ผ่านเมนูบนเครื่องพิมพ์ 1-2 รอบ หากยังไม่ได้ให้ทำ deep cleaning แต่อย่าทำเกิน 3 รอบ เพราะจะสิ้นเปลืองหมึก ถ้ายังไม่หายอาจมีปัญหาที่ท่อหมึก แจ้งซ่อมได้เลยครับ', 1, '2026-07-12 19:51:46', NULL),
(3, 'hardware', 'พิมพ์สีเพี้ยน,สีผิด,สีไม่ตรง,สีออกมาผิด', 'เครื่องพิมพ์พิมพ์สีไม่ตรงหรือสีเพี้ยน', 'ให้ทำ color calibration ผ่านซอฟต์แวร์ของเครื่องพิมพ์ และทดลอง print head cleaning 1 รอบ ถ้าสียังเพี้ยนให้ตรวจสอบว่าตลับหมึกสีนั้นใกล้หมดหรือไม่', 1, '2026-07-12 19:51:46', NULL),
(4, 'hardware', 'เครื่องร้อน,ร้อนเกิน,พัดลมดัง,ร้อนผิดปกติ', 'เครื่องพิมพ์ร้อนผิดปกติแก้อย่างไร', 'ให้ทำความสะอาดช่องระบายอากาศด้วยลมอัด ตรวจสอบว่าวางเครื่องในที่อากาศถ่ายเทได้ หากพัดลมยังดังผิดปกติควรแจ้งซ่อม', 1, '2026-07-12 19:51:46', NULL),
(5, 'hardware', 'scanner,สแกนไม่ได้,error,สแกนเนอร์ไม่ทำงาน', 'Scanner ใช้งานไม่ได้ขึ้น error', 'ลองถอด USB แล้วเสียบใหม่ หรือลองเปลี่ยน port USB ถ้ายังไม่ได้ให้ถอนการติดตั้ง driver แล้วติดตั้งใหม่จากเว็บผู้ผลิต ถ้ายังไม่หายแจ้งซ่อมได้เลยครับ', 1, '2026-07-12 19:51:46', NULL),
(6, 'hardware', 'เปิดไม่ติด,จอดับ,ไฟไม่ขึ้น,เครื่องไม่ทำงาน', 'เครื่องเปิดไม่ติดหรือจอดับทำอย่างไร', 'ลองถอดสายไฟออกรอ 30 วินาที แล้วเสียบใหม่ ถ้ายังไม่ติดให้ลองเปลี่ยนสาย power หรือเช็คว่าปลั๊กไฟทำงานปกติ ถ้ายังไม่หายแจ้งซ่อมได้เลยครับ', 1, '2026-07-12 19:51:46', NULL),
(7, 'software', 'license,ลิขสิทธิ์,activate,หมดอายุ,activation failed', 'ซอฟต์แวร์แจ้งว่าลิขสิทธิ์หมดอายุหรือ activate ไม่ได้', 'กรุณาแจ้ง Serial Number ของซอฟต์แวร์มาที่แอดมิน เพื่อตรวจสอบสถานะและดำเนินการต่ออายุให้ครับ', 1, '2026-07-12 19:51:46', NULL),
(8, 'software', 'อัปเดต,update,ข้อมูลหาย,หลังอัปเดต,อัพเดทแล้วพัง', 'ข้อมูลหายหลังจากอัปเดตซอฟต์แวร์', 'อย่าเพิ่งใช้งานซอฟต์แวร์นั้นต่อ เพื่อป้องกันข้อมูลถูกเขียนทับ แจ้งซ่อมมาได้เลย ช่างจะช่วย restore ข้อมูลให้ครับ', 1, '2026-07-12 19:51:46', NULL),
(9, 'software', 'โปรแกรมค้าง,แฮง,ไม่ตอบสนอง,ค้างหน้าจอ', 'โปรแกรมค้างหรือไม่ตอบสนองทำอย่างไร', 'ลอง Force Quit โปรแกรมแล้วเปิดใหม่ ถ้ายังค้างให้ restart เครื่อง ถ้ายังเกิดซ้ำให้ตรวจสอบว่า RAM เต็มหรือมี process อื่นใช้ทรัพยากรเยอะ แจ้งซ่อมได้เลยถ้าแก้ไม่ได้ครับ', 1, '2026-07-12 19:51:46', NULL),
(10, 'software', 'virus,ไวรัส,มัลแวร์,ถูกแฮก,โดนแฮก', 'เครื่องติดไวรัสหรือมัลแวร์ทำอย่างไร', 'อย่าเปิดโปรแกรมหรือไฟล์ใดๆ เพิ่มเติม ตัดการเชื่อมต่ออินเทอร์เน็ตก่อน แล้วแจ้งช่างมาดูโดยตรง ช่างจะ scan และกำจัดไวรัสให้ครับ', 1, '2026-07-12 19:51:46', NULL),
(11, 'general', 'ประกัน,warranty,ระยะเวลา,สิทธิ์ประกัน,เช็คประกัน', 'ตรวจสอบระยะเวลาประกันทำอย่างไร', 'พิมพ์ Serial Number ของอุปกรณ์มาได้เลยครับ ระบบจะแจ้งสถานะประกันและวันหมดอายุให้ทันที หรือกดปุ่ม \"เช็คประกัน\" ใน Rich Menu ได้เลยครับ', 1, '2026-07-12 19:51:46', '2026-07-22 11:36:48'),
(12, 'general', 'แจ้งซ่อม,ส่งซ่อม,repair,ซ่อม,วิธีแจ้ง', 'ขั้นตอนการแจ้งซ่อมเป็นอย่างไร', 'กดปุ่ม \"แจ้งซ่อม\" ใน Rich Menu แล้วพิมพ์ Serial Number ของอุปกรณ์ที่ต้องการซ่อม จากนั้นระบุอาการและปัญหา เจ้าหน้าที่จะตรวจสอบสิทธิ์ประกันและดำเนินการต่อไปครับ', 1, '2026-07-12 19:51:46', NULL),
(13, 'hardware', 'ยิงไม่เข้า, ไม่เอนเตอร์, ไม่ขึ้นบรรทัดใหม่, Zebra, DS2278, Zebra DS2278 ไม่ Enter', 'เครื่องสแกนบาร์โค้ด (Zebra) ยิงข้อมูลแล้วไม่ขึ้นบรรทัดใหม่ (ไม่ Enter) ต้องทำอย่างไร', 'ปัญหานี้เกิดจากเครื่องสแกนยังไม่ได้เปิดฟังก์ชัน Suffix ครับ วิธีแก้ไขง่ายๆ คือให้สแกนบาร์โค้ดคำสั่ง \"Add an Enter Key\" จากคู่มือ Quick Start Guide ที่มากับตัวเครื่อง ระบบจะตั้งค่าให้กด Enter อัตโนมัติหลังสแกนทันทีค่ะ', 1, '2026-07-13 16:09:11', NULL),
(14, 'hardware', 'เปิดไม่ติด, จอค้าง, เครื่องดับ, รีเซ็ต, PM75, Urovo, ค้าง', 'เครื่องคอมพิวเตอร์พกพา (Point Mobile / UROVO) หน้าจอค้าง หรือเปิดไม่ติด แก้ไขเบื้องต้นอย่างไร', 'แนะนำให้ทำ Hard Reset ครับ โดยการกดปุ่ม Power (เปิด/ปิด) พร้อมกับปุ่ม Volume Down (ลดเสียง) ค้างไว้พร้อมกัน 10-15 วินาที หรือถอดแบตเตอรี่ออกทิ้งไว้ 1 นาทีแล้วใส่กลับเข้าไปใหม่ จากนั้นเสียบชาร์จทิ้งไว้ขั้นต่ำ 30 นาทีแล้วลองเปิดเครื่องอีกครั้งครับ', 1, '2026-07-13 16:09:51', NULL),
(15, 'hardware', 'สแกนไม่ได้, ยิงไม่ติด, แบตต่ำ, แบตหมด, หัวอ่านไม่ติด, PA768', 'ทำไมเครื่องคอมพิวเตอร์พกพา (PDA) แบตเตอรี่ต่ำแล้วยิงบาร์โค้ดไม่ติด หรือหัวอ่านไม่ทำงาน', 'ตัวเครื่องมีระบบเซฟพลังงานอัตโนมัติครับ เมื่อแบตเตอรี่ลดต่ำกว่า 20% ระบบจะลดการจ่ายไฟไปที่หัวอ่านสแกนเนอร์เพื่อเซฟเครื่อง แนะนำให้ผู้ใช้งานนำเครื่องไปเสียบชาร์จให้แบตเตอรี่สูงกว่า 20% ขึ้นไป หัวอ่านจะกลับมาสแกนได้ตามปกติครับ', 1, '2026-07-13 16:10:15', NULL),
(16, 'hardware', 'พิมพ์จาง, พิมพ์ไม่ชัด, ตัวอักษรขาด, ล้างหัวพิมพ์, เครื่องพิมพ์, จาง', 'เครื่องพิมพ์บาร์โค้ด พิมพ์สติกเกอร์ออกมาแล้วตัวอักษรจาง พิมพ์ไม่ชัด หรือข้อความขาดหาย ทำอย่างไร', 'เบื้องต้นให้ปิดเครื่องพิมพ์และถอดปลั๊กออก จากนั้นใช้สำลีแห้งหรือชุบแอลกอฮอล์ (Isopropyl Alcohol) เช็ดทำความสะอาดคราบหมึกหรือคราบกาวเบาๆ บริเวณหัวพิมพ์ความร้อน และตรวจเช็คการตั้งค่าความเข้ม (Darkness) ในคอมพิวเตอร์ว่าตั้งไว้ต่ำเกินไปหรือไม่ครับ', 1, '2026-07-13 16:10:50', NULL),
(17, 'hardware', 'กระดาษไหล, พิมพ์เยื้อง, สติกเกอร์ไม่ตรง, คาลิเบรต, Calibration, ไหลไม่หยุด', 'เครื่องพิมพ์บาร์โค้ดพิมพ์แล้วกระดาษไหลไม่หยุด หรือพิมพ์เยื้องไม่ตรงสติกเกอร์ แก้ไขอย่างไร', 'ตัวเครื่องอาจสูญเสียการจดจำขนาดกระดาษครับ แก้ไขได้โดยการสั่ง Calibrate กระดาษใหม่ โดยกดปุ่ม Feed หน้าเครื่องค้างไว้ตอนเปิดเครื่อง (สัญญานไฟจะกระพริบตามระบบของแต่ละรุ่น) หรือกดสั่งคีย์คำสั่ง Media Calibration ผ่านไดรเวอร์ของเครื่องพิมพ์ในคอมพิวเตอร์ครับ', 1, '2026-07-13 16:11:18', NULL),
(18, 'hardware', 'ชาร์จไม่เข้า, ไฟไม่ขึ้น, แท่นชาร์จ, Cradle, แบตไม่เข้า', 'เครื่องสแกนเนอร์ หรือเครื่อง PDA วางบนแท่นชาร์จ (Cradle) แล้วไฟชาร์จไม่เข้า ต้องเช็คตรงไหน', '1. ให้ตรวจสอบและใช้ผ้าแห้งเช็ดฝุ่นหรือคราบสิ่งสกปรกบริเวณหน้าสัมผัสทองเหลือง (Contact Pins) ทั้งที่ก้นตัวเครื่องและที่แท่นชาร์จ 2. ตรวจเช็คสาย USB และอแดปเตอร์ที่ต่อเข้ากับแท่นชาร์จว่าเสียบแน่นสนิทดีหรือไม่ครับ', 1, '2026-07-13 16:11:50', NULL),
(19, 'hardware', 'Zebra, DS2278, ไม่เอนเตอร์, ไม่ Enter, Suffix, ตั้งค่าEnter', 'Zebra DS2278 ยิงบาร์โค้ดแล้วไม่ขึ้นบรรทัดใหม่ (ไม่ Enter) ต้องตั้งค่าอย่างไร', 'เปิดคู่มือ Quick Start Guide ของ Zebra ไปที่หัวข้อ Suffix แล้วใช้เครื่องสแกนยิงที่บาร์โค้ดคำสั่ง \"Add an Enter Key\" 1 ครั้ง ตัวเครื่องจะเปิดฟังก์ชัน Enter อัตโนมัติหลังสแกนทันทีครับ', 1, '2026-07-13 16:13:25', NULL),
(20, 'hardware', 'Point Mobile, PM75, เปิดไม่ติด, จอค้าง, เครื่องดับ, รีเซ็ต PM75', 'Point Mobile PM75 หน้าจอค้าง หรือเปิดไม่ติด กดรีเซ็ตอย่างไร', 'ให้ทำ Hard Reset เฉพาะรุ่นโดยกดปุ่ม Power พร้อมกับปุ่ม Volume Down (ลดเสียง) ค้างไว้พร้อมกัน 10-15 วินาที เครื่องจะสั่นและทำการรีบูตระบบใหม่ หรือเปิดฝาหลังเพื่อถอดก้อนแบตเตอรี่ออกแล้วใส่ใหม่ครับ', 1, '2026-07-13 16:13:43', NULL),
(21, 'hardware', 'Urovo, DT50, ปุ่มเสีย, ปุ่มสแกนพัง, Key Remap, ปุ่มกดไม่ได้', 'Urovo DT50 ปุ่มกดสแกนด้านข้างเสีย/กดไม่ติด มีวิธีแก้ขัดหน้างานอย่างไร', 'ให้เข้าไปที่แอป \"Key Remap\" ที่ติดมากับเครื่อง Urovo จากนั้นตั้งค่าเปลี่ยนปุ่มสแกน (Scan Trigger) ไปไว้ที่ปุ่มปรับระดับเสียงแทน หรือเปิดใช้งานปุ่มสแกนจำลองบนหน้าจอ (Soft Trigger) ผ่านแอปเพื่อกดแทนปุ่มจริงครับ', 1, '2026-07-13 16:14:01', NULL),
(22, 'hardware', 'Unitech, PA768, แบตต่ำ, เลเซอร์ไม่ขึ้น, ยิงไม่ติด, ยิงบาร์โค้ดไม่ได้', 'Unitech PA768 พอแบตเตอรี่ต่ำกว่า 20% แล้วไฟเลเซอร์สแกนเนอร์ไม่ขึ้น ยิงไม่ติด ทำอย่างไร', 'เป็นระบบ Safe Mode ของ Unitech ครับ แนะนำให้นำเครื่องไปเสียบชาร์จให้แบตเตอรี่เกิน 20% หรือเข้าไปที่แอป Unitech Utility / ScanService เพื่อไปปรับโปรไฟล์การจัดการพลังงาน (Power Profile) ให้หัวอ่านทำงานตอนแบตต่ำครับ', 1, '2026-07-13 16:14:29', NULL),
(23, 'hardware', 'Honeywell, PM43, มอเตอร์ไม่หมุน, Ribbon Error, ผ้าหมึก, สายพานหลุด', 'Honeywell PM43 ขึ้นเตือน Ribbon Error หรือมอเตอร์ผ้าหมึกไม่หมุน เช็คอย่างไร', 'เปิดฝาครอบข้างของ Honeywell PM43 ตรวจดูว่าใส่ผ้าหมึกถูกฝั่งไหม (Ink-in/Ink-out) ลองใช้มือหมุนแกน Ribbon ดูกลไก หรือเปิดฝาห้องเครื่องฝั่งขวาเช็คว่าสายพานเกียร์ (Drive Belt) หลุดหรือหย่อนหรือไม่ครับ', 1, '2026-07-13 16:14:47', NULL),
(24, 'hardware', 'TSC, TE210, กระดาษไหล, ไฟสีแดง, คาลิเบรต, Calibrate TSC', 'TSC TE210 พิมพ์แล้วกระดาษไหลไม่หยุด หรือไฟหน้าเครื่องขึ้นสีแดง/ส้ม คาลิเบรตอย่างไร', 'ให้ทำ Manual Calibration ครับ โดยปิดสวิตช์เครื่องพิมพ์ > กดปุ่ม FEED หน้าเครื่องค้างไว้แล้วเปิดสวิตช์ > รอจนไฟ LED กระพริบเป็นสีแดง-ไฟสีส้ม (Amber) แล้วค่อยปล่อยปุ่ม เครื่องจะวิ่งวัดขนาดกระดาษและจำค่าใหม่ทันทีครับ', 1, '2026-07-13 16:15:06', NULL),
(25, 'hardware', 'Intermec, PR3, ชาร์จไม่เข้า, เปิดไม่ติด, ขั้วแบต, เครื่องพิมพ์พกพา', 'Intermec PR3 ชาร์จไฟไม่เข้า หรือเปิดไม่ติด ตรวจเช็คเบื้องต้นตรงไหน', '1. ตรวจสอบช่องเสียบสายชาร์จ (DC Jack) ด้านข้างเครื่องว่าหลวมหรือหักไหม 2. ถอดก้อนแบตเตอรี่ออกมาเช็คว่ามีฝุ่นหรือคราบกาวบังขั้วทองเหลืองด้านในตัวเครื่องหรือไม่ เช็ดให้สะอาดแล้วดันแบตเตอรี่กลับเข้าไปให้ล็อกสนิทครับ', 1, '2026-07-13 16:15:24', NULL),
(26, 'hardware', 'Test1', 'กินข้าวกับอะไรดี', 'หมูกรอบน่าจะโอเค', 1, '2026-07-14 09:32:00', NULL),
(27, 'software', 'ระบบล่ม', 'ระบบล่ม ,Error ,bug', 'ทางเราจะแจ้งทางทีม Programmer โดยเร็วที่สุดค่ะ', 1, '2026-07-14 09:33:39', NULL),
(28, 'hardware', 'ลบ', 'ลบ', 'ลบ', 0, '2026-07-22 11:36:18', '2026-07-22 11:36:33');
